                LINKTYPE_FC_2_WITH_FRAME_DELIMS = 225,
                /** Solaris ipnet pseudo-header */
                LINKTYPE_IPNET = 226,
                /** CAN (Controller Area Network) frames, with a pseudo-header as supplied by Linux SocketCAN */
                LINKTYPE_CAN_SOCKETCAN = 227,
